<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import { onBeforeRouteLeave, onBeforeRouteUpdate, useRoute, useRouter } from 'vue-router'
import { resourceApi, settingsApi, shortDramaApi, taskApi, imageProviderApi, type ImageProvider, type WorldOverview } from '@/api/modules'
import { directorApi, type DirectorShot, type DirectorDraft, type DirectorWorkflow, type DirectorTake, type ExtraResourceItem, type DirectorAsset } from './directorApi'
import DramaProjectShell from './DramaProjectShell.vue'
import DirectorWorkflowControls from './DirectorWorkflowControls.vue'
import DirectorMediaPreview from './DirectorMediaPreview.vue'
import MediaParameterField from '../generate/MediaParameterField.vue'
import { buildDirectorRequest, applyVideoPrompt, videoPromptKey, applyVideoDefaults } from './directorGeneration'
import AssetPicker from '@/v2/components/AssetPicker.vue'
import MediaViewer from '@/v2/components/MediaViewer.vue'
import { useResourceThumbs } from '../assets/useResourceThumbs'
import { statusMeta, type TaskOutput } from '../tasks/model'
const route=useRoute(),router=useRouter()
const projectId=computed(()=>Number(route.params.projectId)),episodeId=computed(()=>Number(route.params.episodeId))
const shots=ref<DirectorShot[]>([]),workflows=ref<DirectorWorkflow[]>([]),settings=ref<any>({}),activeId=ref<number|null>(null)
const imageProviders=ref<ImageProvider[]>([]),providerError=ref('')
const imageSizes=computed(()=>settings.value?.image_size?.options||[])
const draft=ref<DirectorDraft|null>(null),baseline=ref(''),revision=ref(0),view=ref<'overview'|'make'>(route.query.view==='make'?'make':'overview')
const scope=ref('start'),loading=ref(true),busy=ref(false),error=ref(''),notice=ref(''),filter=ref('all'),sceneFilter=ref(''),selected=ref<number[]>([])
const previewId=ref<number|null>(null),framePreviewId=ref<number|null>(null),picker=ref(false),compare=ref<DirectorTake|null>(null),imagePreview=ref<TaskOutput|null>(null)
const comparison=ref<DirectorTake|null>(null),comparisonId=ref<number|null>(null),taskErrorDetail=ref<{title:string;message:string}|null>(null)
const world=ref<WorldOverview|null>(null)
const frameModal=ref(false),pickerTarget=ref<'extra'|'frame'>('extra'),pickerMedia=ref<'image'|'audio'|'video'>('image')
const contextPicker=ref(false),savingRefs=ref(false)
const pickCharacters=ref<number[]>([]),pickLocation=ref<number|null>(null),pickProps=ref<number[]>([])
const comparisonOptions=computed(()=>active.value?.takes.filter(t=>t.scope===comparison.value?.scope&&t.resource.media_type===comparison.value?.resource.media_type&&t.id!==comparison.value?.id)||[])
const comparisonOther=computed(()=>comparisonOptions.value.find(t=>t.id===comparisonId.value)||comparisonOptions.value[0])
function compareVersions(take:DirectorTake){comparison.value=take;comparisonId.value=comparisonOptions.value.find(t=>t.is_selected)?.id||comparisonOptions.value[0]?.id||null}
const plan=ref<Array<{shot:DirectorShot;body:any;compiled:any;result?:string}>>([])
const {thumbs,load:loadThumbs,clear}=useResourceThumbs()
let savingDraft:Promise<boolean>|null=null
let poll:ReturnType<typeof setInterval>|null=null,refreshing=false,request=0
const clone=<T,>(v:T):T=>JSON.parse(JSON.stringify(v))
const message=(e:any)=>String(e.response?.data?.detail||e.message||'操作失败')
const active=computed(()=>shots.value.find(s=>s.id===activeId.value)||null)
const previousShot=computed(()=>{const index=shots.value.findIndex(s=>s.id===activeId.value);return index>0?shots.value[index-1]:null})
const previousSelectedVideo=computed(()=>previousShot.value?videoTake(previousShot.value)||null:null)
const dirty=computed(()=>!!draft.value&&JSON.stringify(draft.value)!==baseline.value)
const frame=computed(()=>draft.value?.frames.find(f=>f.id===scope.value))
const running=(s:DirectorShot)=>s.tasks.some(t=>['PENDING','DISPATCHING','QUEUED','RUNNING','FINALIZING'].includes(t.status))
const videoTake=(s:DirectorShot)=>s.takes.find(t=>t.scope==='video'&&t.is_selected)
const videoTakes=computed(()=>active.value?.takes.filter(t=>t.scope==='video'&&t.resource.media_type==='video')||[])
const frameTakes=computed(()=>active.value?.takes.filter(t=>t.scope===scope.value&&t.resource.media_type==='image')||[])
const currentVideo=computed(()=>videoTakes.value.find(t=>t.id===previewId.value)||videoTakes.value.find(t=>t.is_selected)||videoTakes.value[0])
const currentFrame=computed(()=>frameTakes.value.find(t=>t.id===framePreviewId.value)||frameTakes.value.find(t=>t.is_selected)||frameTakes.value[0])
const videoWorkflow=computed(()=>workflows.value.find(w=>w.workflow_version_id===draft.value?.video_workflow_version_id))
const promptFields=[['visual_description','画面描述'],['action','动作发展'],['expression','可观察表情'],['dialogue','对白（含说话人）'],['timeline_storyboard','时间轴分镜'],['continuity','连续性入口 / 出口'],['shot_size','景别'],['camera_angle','机位角度'],['camera_movement','镜头运动'],['composition','构图与结尾状态'],['transition','转场'],['visual_style','视觉风格'],['atmosphere','环境氛围与声音'],['negative_constraints','负面约束']]
watch(()=>[activeId.value,draft.value?.video_workflow_version_id],()=>{if(draft.value&&active.value)applyVideoDefaults(draft.value,videoWorkflow.value,active.value.duration,active.value.aspect_ratio,settings.value)},{flush:'post'})
function markPromptInput(key:string){if(draft.value&&!draft.value.prompt_input_overrides.includes(key))draft.value.prompt_input_overrides.push(key)}
function assetPromptKey(asset:DirectorAsset){return `${asset.role}:${asset.entity_id}`}
function assetPromptDescription(asset:DirectorAsset){return draft.value?.prompt_asset_descriptions[assetPromptKey(asset)]??asset.description}
const completed=computed(()=>shots.value.filter(s=>videoTake(s)).length)
const scenes=computed(()=>[...new Map(shots.value.map(s=>[s.scene_id,s.scene])).entries()])
const visibleShots=computed(()=>shots.value.filter(s=>(!sceneFilter.value||s.scene_id===Number(sceneFilter.value))&&(filter.value==='all'||filter.value==='ready'&&!!s.selected_frames.start||filter.value==='unfinished'&&!videoTake(s)||filter.value==='running'&&running(s)||filter.value==='stale'&&s.takes.some(t=>t.is_selected&&t.stale))))
const modeLabels:Record<string,string>={manual:'手动工作流输入',first:'首帧驱动',first_last:'首尾帧驱动',references:'角色 / 场景参考驱动'}
const scopeLabel=(id:string)=>id==='video'?'视频':id==='start'?'首帧':id==='end'?'尾帧':'关键帧'
const mediaLabel=(t:string)=>t==='image'?'图片':t==='audio'?'声音':'视频'
const extraIcon=(t:string)=>t==='image'?'▧':t==='audio'?'♪':'▶'
const extraLabel=(e:ExtraResourceItem)=>e.label||e.filename||`素材 #${e.resource_id}`
const sortedExtras=computed(()=>[...(draft.value?.asset_choices.extras||[])].sort((a,b)=>Number(b.enabled??true)-Number(a.enabled??true)||(a.order||0)-(b.order||0)||a.resource_id-b.resource_id))
function sortedIndexOf(e:ExtraResourceItem){return draft.value?.asset_choices.extras.findIndex(x=>x.resource_id===e.resource_id)??-1}
const worldCharacters=computed(()=>world.value?.characters||[]),worldLocations=computed(()=>world.value?.locations||[]),worldProps=computed(()=>world.value?.props||[])
const characterAssets=computed(()=>active.value?.assets.filter(a=>a.role==='character_references')||[])
const locationAsset=computed(()=>active.value?.assets.find(a=>a.role==='scene_references')||null)
const videoMediaParams=computed(()=>videoWorkflow.value?.parameters.filter(p=>['image','video','audio'].includes(p.type))||[])
const checkedMedia=computed(()=>{
 if(!draft.value||!active.value)return []
 const items:Array<{resource_id:number;media_type:string;label:string;rank:number}>=[]
 const add=(rid:number|null|undefined,type:string,label:string,key:string)=>{if(rid)items.push({resource_id:rid,media_type:type,label,rank:checkRank(key)})}
 for(const f of draft.value.frames)if(f.enabled!==false)add(active.value.selected_frames[f.id],'image',scopeLabel(f.id),`frame:${f.id}`)
 for(const e of sortedExtras.value)if(e.enabled)add(e.resource_id,e.media_type,extraLabel(e),`extra:${e.resource_id}`)
 for(const a of active.value.assets){const character=a.role==='character_references',location=a.role==='scene_references';if(character?isEnabledAsset(a):location?isLocationEnabled.value:isPropEnabled(a.entity_id))add(a.resource_id,'image',a.name,character?`char:${a.entity_id}`:location?'location':`prop:${a.entity_id}`)}
 return items.sort((a,b)=>a.rank-b.rank).filter((item,i,list)=>list.findIndex(x=>x.resource_id===item.resource_id)===i)
})
function worldThumb(kind:'character'|'location'|'prop',id:number,resourceId:number|null){return resourceId&&thumbs.value[resourceId]?thumbs.value[resourceId]:''}
function loadWorldThumbs(){const items=[...worldCharacters.value.flatMap(c=>[c.primary_resource_id,...(c.variants||[]).map(v=>v.primary_resource_id)]),...worldLocations.value.map(l=>l.primary_resource_id),...worldProps.value.map(p=>p.resource_id)].filter((id):id is number=>!!id).map(id=>({id,media_type:'image'} as any));if(items.length)void loadThumbs([...new Map(items.map(i=>[i.id,i])).values()])}
watch(world,()=>loadWorldThumbs(),{immediate:true})
function previewThumb(s:DirectorShot){return videoTake(s)?.resource_id||s.selected_frames.start||s.takes[0]?.resource_id}
function previewImage(resourceId:number|null|undefined,label:string){if(resourceId)imagePreview.value={id:resourceId,filename:label+'.png',media_type:'image',mime:'image/png',width:null,height:null,duration:null}}
function shotTitle(s:DirectorShot){return s.title||s.description||`镜头 ${s.shot_no}`}
async function thumbnails(){const resources=shots.value.flatMap(s=>[...s.takes.map(t=>t.resource),...s.assets.filter(a=>a.resource_id).map(a=>({id:a.resource_id,media_type:'image'})),...Object.values(s.selected_frames).map(id=>({id,media_type:'image'})),...(s.extras||[]).map(e=>({id:e.resource_id,media_type:e.media_type}))]);await loadThumbs([...new Map(resources.map(r=>[r.id,r])).values()] as any)}
function receive(shot:DirectorShot){const index=shots.value.findIndex(s=>s.id===shot.id);if(index>=0)shots.value[index]=shot}
function selectDraft(shot:DirectorShot){activeId.value=shot.id;draft.value=clone(shot.draft);draft.value.prompt_inputs=draft.value.prompt_inputs||{};draft.value.prompt_input_overrides=draft.value.prompt_input_overrides||[];draft.value.prompt_asset_descriptions=draft.value.prompt_asset_descriptions||{};if(!draft.value.asset_choices)draft.value.asset_choices={extras:[],characters:[],prop_orders:{}};draft.value.asset_choices.prop_orders=draft.value.asset_choices.prop_orders||{};draft.value.asset_choices.extras.forEach((e,i)=>{if(e.enabled==null){e.enabled=true;e.order=e.order||i+1}});draft.value.frames.forEach((f,i)=>{if(f.enabled==null){f.enabled=true;f.order=f.order||i+1}});baseline.value=JSON.stringify(draft.value);revision.value=shot.revision;scope.value='start';previewId.value=null;framePreviewId.value=null;frameModal.value=false}
async function saveDraft(){if(!dirty.value||!active.value||!draft.value)return true;const id=active.value.id;const snapshot=clone(draft.value);try{const saved=await directorApi.save(projectId.value,id,revision.value,snapshot);receive(saved);revision.value=saved.revision;baseline.value=JSON.stringify(snapshot);return true}catch(e){error.value=message(e);return false}}
function save():Promise<boolean>{if(savingDraft)return savingDraft;savingDraft=saveDraft().finally(()=>{savingDraft=null});return savingDraft}
async function chooseShot(shot:DirectorShot){if(busy.value||!await save())return;selectDraft(shot);view.value='make';void router.push({query:{...route.query,view:'make',shot:shot.id}})}
async function load(){const marker=++request;loading.value=true;error.value='';providerError.value='';try{const [result,ws,selects,providers,worldData]=await Promise.all([directorApi.overview(projectId.value,episodeId.value),directorApi.workflows(projectId.value),settingsApi.getSelectOptions(),imageProviderApi.list().catch(()=>{providerError.value='读取 Gemini 提供方失败，请重新载入';return [] as ImageProvider[]}),shortDramaApi.world(projectId.value).catch(()=>null)]);if(marker!==request)return;shots.value=result.shots;workflows.value=ws;settings.value=selects;imageProviders.value=providers.filter(p=>p.enabled);world.value=worldData;const shot=shots.value.find(s=>s.id===Number(route.query.shot))||shots.value[0];if(shot)selectDraft(shot);else{activeId.value=null;draft.value=null}selected.value=[];await thumbnails()}catch(e){if(marker===request)error.value=message(e)}finally{if(marker===request)loading.value=false}}
async function refresh(){if(refreshing||busy.value||loading.value)return;refreshing=true;const marker=request;try{const result=await directorApi.overview(projectId.value,episodeId.value);if(marker!==request)return;shots.value=result.shots;await thumbnails()}catch{}finally{refreshing=false}}
async function reloadWorkflows(){workflows.value=await directorApi.workflows(projectId.value);notice.value='输入用途已保存，请自动填写或检查生成参数'}
const aiPrompting=ref(false)
async function aiVideoPrompt(){
 if(!active.value||!draft.value||aiPrompting.value||busy.value)return
 if(!videoPromptKey(videoWorkflow.value)){error.value='请先选择带视频提示词输入的工作流';return}
 const shotId=active.value.id,versionId=draft.value.video_workflow_version_id
 aiPrompting.value=true;error.value=''
 try{
  if(!await save())return
  const result=await directorApi.videoPrompt(projectId.value,shotId)
  if(!draft.value||active.value?.id!==shotId||draft.value.video_workflow_version_id!==versionId)throw new Error('镜头或工作流已切换，未覆盖当前参数，请重新生成提示词')
  applyVideoPrompt(draft.value,videoWorkflow.value,result.prompt)
  notice.value='已将综合提示词（含原剧本对白）填入工作流提示词；已使用下方编辑后的提示词来源'
 }catch(e){error.value=message(e)}finally{aiPrompting.value=false}
}
function bodyFor(s:DirectorShot,target:string,values:DirectorDraft){return buildDirectorRequest(target,values,workflows.value)}
function chooseImageService(service:'comfyui'|'gemini_image'){
 if(!frame.value)return
 frame.value.generation_service=service
 if(service==='gemini_image'){
  if(!frame.value.gemini_provider_id)frame.value.gemini_provider_id=(imageProviders.value.find(p=>p.is_default)||imageProviders.value[0])?.id||null
  if(!frame.value.gemini_params.size)frame.value.gemini_params.size=settings.value?.image_size?.default_value||imageSizes.value[0]?.value||''
  if(!('reference_resource_ids' in frame.value.gemini_params))fillGeminiReferences()
 }
}
function fillGeminiReferences(){if(frame.value)frame.value.gemini_params={...frame.value.gemini_params,reference_resource_ids:[...new Set(active.value?.assets.map(a=>a.resource_id).filter(Boolean)||[])]}}

async function autofill(target:string){if(!active.value||!draft.value||busy.value)return;busy.value=true;error.value='';try{if(!await save())return;const body=bodyFor(active.value,target,draft.value);if(!body.workflow_version_id)throw new Error('请先选择工作流');const workflow=workflows.value.find(w=>w.workflow_version_id===body.workflow_version_id);for(const key of Object.keys(workflow?.mapping||{}))delete body.params[key];const result=await directorApi.compile(projectId.value,active.value.id,body);if(target==='video')draft.value.video_params=result.params;else if(frame.value)frame.value.params=result.params;notice.value=[...result.errors,...result.warnings].join('；')||'已按当前镜头刷新用途参数，其他手动参数保留'}catch(e){error.value=message(e)}finally{busy.value=false}}
async function prepare(target:string,batch=false){if(!active.value||!draft.value||busy.value)return;busy.value=true;error.value='';plan.value=[];try{if(!await save())return;const targets=batch?shots.value.filter(s=>selected.value.includes(s.id)):[active.value];for(const shot of targets){const values=shot.id===active.value.id?draft.value:shot.draft;const body=bodyFor(shot,target,values);try{if(body.generation_service==='comfyui'&&!body.workflow_version_id)throw new Error('尚未为此镜头选择工作流');const compiled=await directorApi.compile(projectId.value,shot.id,body);Object.assign(body,{expected_fingerprint:compiled.fingerprint});plan.value.push({shot,body,compiled})}catch(e){plan.value.push({shot,body,compiled:{errors:[message(e)],warnings:[],params:{}}})}}}finally{busy.value=false}}
async function executePlan(){if(busy.value)return;busy.value=true;error.value='';try{for(const item of plan.value){if(item.compiled.errors.length||item.result==='已提交')continue;try{const result=await directorApi.generate(projectId.value,item.shot.id,item.body);item.result=`已提交`;notice.value=`任务 #${result.task_id} 已进入平台队列`}catch(e){item.result=message(e)}}}finally{busy.value=false;await refresh()}}
async function adopt(take:DirectorTake){if(!active.value||busy.value)return;busy.value=true;error.value='';try{if(!await save())return;await directorApi.adopt(projectId.value,take.id);const result=await directorApi.shot(projectId.value,active.value.id);receive(result);revision.value=result.revision;notice.value=`已采用${scopeLabel(take.scope)} Take ${take.take_no}，其他帧和视频采用保持不变`}catch(e){error.value=message(e)}finally{busy.value=false}}
function addFrame(){if(!draft.value||!active.value)return;const id=`key_${crypto.randomUUID().slice(0,8)}`;draft.value.frames.splice(-1,0,{id,kind:'key',time:active.value.duration/2,prompt:'',workflow_version_id:null,params:{},generation_service:'comfyui',gemini_provider_id:null,gemini_params:{},});scope.value=id}
function removeFrame(id:string){if(!draft.value)return;draft.value.frames=draft.value.frames.filter(f=>f.id!==id);if(scope.value===id)scope.value='start'}
function openFrameModal(id:string){scope.value=id;framePreviewId.value=null;frameModal.value=true}
async function closeFrameModal(){frameModal.value=false;if(dirty.value)await save()}
async function importFrameItems(items:any[]){if(!active.value||!items[0])return;busy.value=true;error.value='';try{if(!await save())return;await directorApi.importFrame(projectId.value,active.value.id,scope.value,items[0].id);receive(await directorApi.shot(projectId.value,active.value.id));await thumbnails();notice.value='已加入当前帧候选，请预览后采用'}catch(e){error.value=message(e)}finally{busy.value=false}}
async function usePreviousVideoTail(){const current=active.value,previous=previousShot.value,video=previousSelectedVideo.value;if(!current||!previous||!video||busy.value)return;busy.value=true;error.value='';try{if(!await save())return;const frames=await resourceApi.extractFrames(video.resource_id,{timestamps:'-0.05'});const extracted=frames?.[0];if(!extracted?.id)throw new Error('上一镜已采用视频无法提取尾帧，请检查视频文件和 ffmpeg');const imported=await directorApi.importFrame(projectId.value,current.id,'start',extracted.id);const take=imported.takes.find(t=>t.scope==='start'&&t.resource_id===extracted.id);if(!take)throw new Error('尾帧已提取，但加入当前镜头首帧失败');await directorApi.adopt(projectId.value,take.id);const updated=await directorApi.shot(projectId.value,current.id);receive(updated);revision.value=updated.revision;await thumbnails();notice.value=`已将上一镜 S${String(previous.shot_no).padStart(2,'0')} 已采用视频的尾帧设为当前首帧`}catch(e){error.value=message(e)}finally{busy.value=false}}
function addExtras(items:any[]){if(!draft.value||!items.length)return;const fresh:any[]=[];for(const item of items){if(draft.value.asset_choices.extras.some(e=>e.resource_id===item.id))continue;const media=item.media_type==='audio'?'audio':item.media_type==='video'?'video':'image';const max=nextOrder();draft.value.asset_choices.extras.push({resource_id:item.id,media_type:media,label:item.filename||'',enabled:true,order:max});fresh.push(item)}if(fresh.length){void loadThumbs(fresh);notice.value=`已按顺序勾选 ${fresh.length} 个库素材；生成预检时按勾选顺序填入工作流输入`}}
// ---- 视频资源统一勾选体系：关键帧 / 库素材 / 上下文资产共享一个勾选顺序空间 ----
function nextOrder(){const c=draft.value!.asset_choices;return Math.max(0,...draft.value!.frames.map(f=>f.order||0),...c.extras.map(x=>x.order||0),...c.characters.map(x=>x.order||0),c.location_order||0,...Object.values(c.prop_orders||{}))+1}
function checkedEntries(){const c=draft.value!.asset_choices;const list:[string,number,number][]=[];draft.value?.frames.forEach((f,i)=>{if(f.enabled!==false)list.push([`frame:${f.id}`,f.order||0,i])});c.extras.forEach((e,i)=>{if(e.enabled)list.push([`extra:${e.resource_id}`,e.order||0,i])});c.characters.forEach((x,i)=>{if(x.enabled)list.push([`char:${x.character_id}`,x.order||0,i])});if(c.location_enabled)list.push(['location',c.location_order||0,0]);Object.entries(c.prop_orders||{}).forEach(([pid,order])=>{if(order)list.push([`prop:${pid}`,order,0])});list.sort((a,b)=>a[1]-b[1]);const rank=new Map<string,number>();list.forEach(([key],i)=>rank.set(key,i+1));return rank}
function checkRank(key:string){return checkedEntries().get(key)||0}
function toggleFrameCheck(f:{id:string;enabled?:boolean;order?:number},checked:boolean){if(checked){f.enabled=true;f.order=nextOrder()}else{f.enabled=false;f.order=0}}
function toggleExtraCheck(e:ExtraResourceItem,checked:boolean){if(checked){e.enabled=true;e.order=nextOrder()}else{e.enabled=false;e.order=0}}
function charChoice(cid:number){const c=draft.value!.asset_choices;let item=c.characters.find(x=>x.character_id===cid);if(!item){item={character_id:cid,image_mode:'primary'};c.characters.push(item)}return item}
function toggleCharacterCheck(cid:number,checked:boolean){const item=charChoice(cid);if(checked){item.enabled=true;item.order=nextOrder()}else{item.enabled=false;item.order=0}}
function toggleLocationCheck(checked:boolean){const c=draft.value!.asset_choices;c.location_enabled=checked;c.location_order=checked?nextOrder():0}
function togglePropCheck(pid:number,checked:boolean){const c=draft.value!.asset_choices;c.prop_orders=c.prop_orders||{};if(checked)c.prop_orders[String(pid)]=nextOrder();else delete c.prop_orders[String(pid)]}
function removeExtra(index:number){draft.value?.asset_choices.extras.splice(index,1)}
function moveExtra(index:number,delta:number){const list=draft.value?.asset_choices.extras;if(!list)return;const target=index+delta;if(target<0||target>=list.length)return;const a=list[index],b=list[target];[list[index],list[target]]=[b,a];const tmp=a.order;a.order=b.order;b.order=tmp}
function onPickerSelect(items:any[]){picker.value=false;if(pickerTarget.value==='frame')return importFrameItems(items);addExtras(items)}
function openExtrasPicker(){pickerTarget.value='extra';picker.value=true}
function paramHas(key:string,rid:number){const value=draft.value?.video_params[key];return Array.isArray(value)&&value.includes(rid)}
function toggleExtraParam(key:string,rid:number,multiple:boolean){if(!draft.value)return;const current=draft.value.video_params[key];if(multiple){const list=Array.isArray(current)?current.filter(v=>v!==rid):[];if(!Array.isArray(current)||!current.includes(rid))list.push(rid);draft.value.video_params[key]=list}else if(rid)draft.value.video_params[key]=rid;else delete draft.value.video_params[key]}
function imageModeOf(cid:number){return draft.value?.asset_choices.characters.find(c=>c.character_id===cid)?.image_mode||'primary'}
async function setImageMode(cid:number,mode:'primary'|'turnaround'){
 if(!draft.value||busy.value)return
 charChoice(cid).image_mode=mode
 busy.value=true;error.value=''
 try{if(await save()){await thumbnails();notice.value=mode==='turnaround'?'已切换为角色三视图':'已切换为角色基本图'}}
 catch(e){error.value=message(e)}
 finally{busy.value=false}
}
function isEnabledAsset(asset:DirectorAsset){return draft.value?.asset_choices.characters.find(c=>c.character_id===asset.entity_id)?.enabled??true}
const isLocationEnabled=computed(()=>!!draft.value?.asset_choices.location_enabled)
function isPropEnabled(pid:number){return !!draft.value?.asset_choices.prop_orders?.[String(pid)]}
function variantsOf(cid:number){return worldCharacters.value.find(c=>c.id===cid)?.variants||[]}
function propAsset(pid:number){return active.value?.assets.find(a=>a.role==='prop_references'&&a.entity_id===pid)}
function propResourceId(pid:number){return propAsset(pid)?.resource_id||worldProps.value.find(p=>p.id===pid)?.resource_id||null}
function propName(pid:number){return worldProps.value.find(p=>p.id===pid)?.name||propAsset(pid)?.name||`道具 #${pid}`}
async function applyRefs(characterIds:number[],bindings:Record<string,number|null>,locationId:number|null,propIds:number[]){if(!active.value||savingRefs.value)return;savingRefs.value=true;error.value='';try{if(!await save())return;const choices=draft.value!.asset_choices;const knownChars=new Set(choices.characters.map(c=>c.character_id));for(const cid of characterIds)if(!knownChars.has(cid)){choices.characters.push({character_id:cid,image_mode:'primary',enabled:true,order:nextOrder()})}choices.characters=choices.characters.filter(c=>characterIds.includes(c.character_id));if(locationId!=null&&!choices.location_enabled&&choices.location_order==0){choices.location_enabled=true;choices.location_order=nextOrder()}else if(locationId==null){choices.location_enabled=false;choices.location_order=0}const orders:Record<string,number>={};for(const pid of propIds){const current=choices.prop_orders?.[String(pid)];orders[String(pid)]=current||nextOrder()}choices.prop_orders=orders;const result=await directorApi.updateRefs(projectId.value,active.value.id,{character_ids:characterIds,bindings,location_id:locationId,prop_ids:propIds});receive(result);revision.value=result.revision;await thumbnails();notice.value='镜头上下文已更新；依赖旧参考的候选将标记为依赖已更新'}catch(e){error.value=message(e)}finally{savingRefs.value=false}}
function currentBindings(){const map:Record<string,number|null>={};for(const asset of characterAssets.value)map[String(asset.entity_id)]=asset.variant_id??null;return map}
function openContextPicker(){if(!active.value)return;pickCharacters.value=[...(active.value.character_ids||[])];pickLocation.value=active.value.location_id??null;pickProps.value=[...(active.value.prop_ids||[])];contextPicker.value=true}
function togglePick(list:number[],id:number){const index=list.indexOf(id);if(index>=0)list.splice(index,1);else list.push(id)}
function applyContext(){applyRefs([...pickCharacters.value],currentBindings(),pickLocation.value,[...pickProps.value]);contextPicker.value=false}
function setVariant(cid:number,variantId:number|null){if(!active.value)return;const bindings=currentBindings();bindings[String(cid)]=variantId;applyRefs([...(active.value.character_ids||[])],bindings,active.value.location_id??null,[...(active.value.prop_ids||[])])}
function removeCharacter(cid:number){if(!active.value)return;const bindings=currentBindings();delete bindings[String(cid)];applyRefs((active.value.character_ids||[]).filter(id=>id!==cid),bindings,active.value.location_id??null,[...(active.value.prop_ids||[])])}
function removeLocation(){if(!active.value)return;applyRefs([...(active.value.character_ids||[])],currentBindings(),null,[...(active.value.prop_ids||[])])}
function removeProp(pid:number){if(!active.value)return;applyRefs([...(active.value.character_ids||[])],currentBindings(),active.value.location_id??null,(active.value.prop_ids||[]).filter(id=>id!==pid))}
function applyTaskParams(task:DirectorShot['tasks'][number]){
 if(!draft.value||busy.value)return
 const params=clone(task.params||{})
 if(task.scope==='video'){
  draft.value.video_workflow_version_id=task.workflow_version_id
  draft.value.video_mode=task.mode||'manual'
  draft.value.video_params=params
 }else{
  const target=draft.value.frames.find(item=>item.id===task.scope)
  if(!target){error.value=`任务 #${task.id} 对应的关键帧已被移除，无法回填`;return}
  scope.value=target.id
  target.generation_service=task.generation_service||'comfyui'
  if(target.generation_service==='gemini_image'){
   target.gemini_provider_id=task.provider_config_id
   target.gemini_params=params
  }else{
   target.workflow_version_id=task.workflow_version_id
   target.params=params
  }
  framePreviewId.value=null;frameModal.value=true
 }
 notice.value=`已应用任务 #${task.id} 的${scopeLabel(task.scope)}参数，请检查后再生成`
}
function taskErrorText(task:any){return String(task.error||task.sync_error||'').trim()}
function openTaskError(task:any){taskErrorDetail.value={title:`任务 #${task.id} · ${scopeLabel(task.scope)}`,message:taskErrorText(task)}}
async function taskAction(id:number,action:'cancel'|'retry'|'sync'){error.value='';try{if(action==='sync')await shortDramaApi.reconcileProductionTask(projectId.value,id);else await taskApi[action](id);await refresh()}catch(e){error.value=message(e)}}
function toggle(id:number){selected.value=selected.value.includes(id)?selected.value.filter(v=>v!==id):[...selected.value,id]}
async function setView(value:'overview'|'make'){if(!await save())return;view.value=value;void router.push({query:{...route.query,view:value}})}
function beforeUnload(event:BeforeUnloadEvent){if(dirty.value){event.preventDefault();event.returnValue=''}}
onBeforeRouteLeave(async()=>busy.value?false:await save())
onBeforeRouteUpdate(async(to,from)=>{if(to.params.episodeId!==from.params.episodeId||to.params.projectId!==from.params.projectId||to.query.shot!==from.query.shot||to.query.view!==from.query.view)return busy.value?false:await save()})
watch(()=>[route.params.projectId,route.params.episodeId],()=>void load())
watch(()=>[route.query.view,route.query.shot],()=>{view.value=route.query.view==='make'?'make':'overview';const shot=shots.value.find(s=>s.id===Number(route.query.shot));if(shot&&shot.id!==activeId.value)selectDraft(shot)})
onMounted(()=>{
 const jobId=String(route.query.promptJob||'')
 if(jobId){
  const key=`drama-prompt-job:${projectId.value}:${episodeId.value}`
  try{const result=JSON.parse(sessionStorage.getItem(key)||'null');if(result?.job_id===Number(jobId)&&result.failed?.length){notice.value=`技能生成完成，${result.failed.length} 个镜头失败；成功镜头已保存，可逐镜头检查或重试`;sessionStorage.removeItem(key)}else notice.value='short-drama-director /生成视频提示词 已完成，结果已保存到各镜头'}catch{notice.value='视频提示词生成任务已完成'}
 }
 void load();poll=setInterval(()=>void refresh(),4000);window.addEventListener('beforeunload',beforeUnload)
})
onUnmounted(()=>{request++;if(poll)clearInterval(poll);clear();window.removeEventListener('beforeunload',beforeUnload)})
</script>

<template><DramaProjectShell active="director" page-title="导演工作台" :save-state="busy?'处理中…':dirty?'有未保存修改':'已保存'">
<template #actions><button class="shell-save" :disabled="busy||!dirty" @click="save">保存草稿</button></template>
<div class="director-page"><nav class="workspace-tabs" aria-label="导演视图"><button :class="{active:view==='overview'}" :disabled="busy" @click="setView('overview')">镜头总览</button><button :class="{active:view==='make'}" :disabled="busy||!active" @click="setView('make')">镜头制作</button></nav>
<p v-if="error" class="banner error" role="alert">{{error}} <button :disabled="busy" @click="load">重新载入</button></p><p v-if="notice" class="banner notice">{{notice}}</p>
<div v-if="loading" class="empty">正在加载当前分集的镜头与制作状态…</div><div v-else-if="!shots.length" class="empty"><h2>当前集还没有镜头</h2><p>请先在拍摄清单中确认分镜，再进入导演制作。</p><button @click="router.push(`/v2/drama/projects/${projectId}/episodes/${episodeId}/manifest`)">打开拍摄清单</button></div>
<template v-else>
<section v-if="view==='overview'" class="overview"><header class="overview-head"><div><small>DIRECTOR WORKSPACE</small><h1>镜头总览</h1><p>从已确认剧本到画面，按镜头推进制作。</p></div><button class="primary" :disabled="busy||!selected.length" @click="prepare('video',true)">批量视频预检（{{selected.length}}）</button></header><div class="overview-tools"><span>{{shots.length}} 个镜头 · 首帧就绪 {{shots.filter(s=>s.selected_frames.start).length}} · 视频已采用 {{completed}}</span><select v-model="sceneFilter" aria-label="场次筛选"><option value="">全部场次</option><option v-for="[id,name] in scenes" :key="id" :value="id">{{name}}</option></select><select v-model="filter" aria-label="制作状态筛选"><option value="all">全部状态</option><option value="ready">首帧就绪</option><option value="unfinished">视频未采用</option><option value="running">生成中</option><option value="stale">依赖已更新</option></select></div>
<div class="shot-grid"><article v-for="shot in visibleShots" :key="shot.id" class="shot-card"><div class="card-cover"><button class="cover-button" @click="chooseShot(shot)"><img v-if="previewThumb(shot)&&thumbs[previewThumb(shot)!]" :src="thumbs[previewThumb(shot)!]" :alt="shot.description"/><span v-else>▧<small>待制作画面</small></span></button><label class="card-check"><input type="checkbox" :checked="selected.includes(shot.id)" :aria-label="`选择镜头 ${shot.shot_no}`" @change="toggle(shot.id)"/> S{{String(shot.shot_no).padStart(2,'0')}}</label><span v-if="running(shot)" class="card-status">制作中</span></div><div class="card-copy"><small>{{shot.scene}}</small><h3>{{shot.description||`镜头 ${shot.shot_no}`}}</h3><p>{{shot.duration}}s · {{shot.camera||'固定镜头'}}</p><div class="asset-chips"><span v-for="asset in shot.assets" :key="asset.role+asset.name">{{asset.name}}</span></div><p>关键帧：{{shot.selected_frames.start?'首帧已采用':'首帧待制作'}} / {{shot.selected_frames.end?'尾帧已采用':'尾帧待制作'}}</p><p>视频：{{videoTake(shot)?`已采用 Take ${videoTake(shot)!.take_no}`:'待生成 / 采用'}}</p><p v-if="shot.takes.some(t=>t.is_selected&&t.stale)" class="warning">依赖已更新 · 历史结果保留</p><button class="enter" @click="chooseShot(shot)">进入制作 →</button></div></article></div><p v-if="!visibleShots.length" class="empty">没有符合条件的镜头</p></section>
<section v-else-if="active&&draft" class="make"><header class="make-heading"><div><small>{{active.scene}}</small><h1 :title="`镜头 S${String(active.shot_no).padStart(2,'0')} · ${active.description}`">镜头 S{{String(active.shot_no).padStart(2,'0')}} · {{active.description}}</h1><p>{{active.duration}} 秒 · {{active.camera||'固定镜头'}}</p></div><div class="pager"><button :disabled="busy||shots[0].id===active.id" @click="chooseShot(shots[shots.findIndex(s=>s.id===active!.id)-1])">上一镜</button><button :disabled="busy||shots[shots.length-1].id===active.id" @click="chooseShot(shots[shots.findIndex(s=>s.id===active!.id)+1])">下一镜</button></div></header>
<div class="make-layout"><aside class="shot-rail"><button v-for="shot in shots" :key="shot.id" :disabled="busy" :class="{active:shot.id===active.id,adopted:!!videoTake(shot)}" :title="shotTitle(shot)" @click="chooseShot(shot)"><b>S{{String(shot.shot_no).padStart(2,'0')}}</b><span class="rail-title">{{shotTitle(shot)}}</span></button></aside>
<main class="make-canvas"><div class="section-heading"><h2>视频预览</h2><span v-if="currentVideo" class="tag">Take {{currentVideo.take_no}} · {{currentVideo.is_selected?'已采用':'候选'}}</span></div><DirectorMediaPreview :resource-id="currentVideo?.resource_id" media-type="video" label="视频候选将在这里显示"/><div class="take-strip"><button v-for="take in videoTakes" :key="take.id" :class="{active:currentVideo?.id===take.id}" @click="previewId=take.id"><img :src="thumbs[take.resource_id]"/>Take {{take.take_no}} {{take.is_selected?'✓':''}}<span v-if="take.stale">依赖已更新</span></button><span v-if="!videoTakes.length" class="muted">生成成功后保留所有视频候选，不自动覆盖已采用版本。</span></div><div v-if="currentVideo" class="candidate-actions"><button :disabled="busy||currentVideo.is_selected" @click="adopt(currentVideo)">采用此视频</button><button @click="compare=currentVideo">放大查看</button><button v-if="videoTakes.length>1" @click="compareVersions(currentVideo)">对比版本</button><span v-if="currentVideo.stale" class="warning">此版本的剧本、资产或帧输入已更新</span></div>
<section class="video-plan"><div class="section-heading"><div><h2>视频生成方案 · ComfyUI</h2><p>选择工作流与输入模式；图片 / 声音 / 视频输入项可从右侧视频资源按序选择。</p></div><button :disabled="busy" @click="autofill('video')">按当前镜头刷新用途参数</button></div><DirectorWorkflowControls :key="active.id" :project-id="projectId" :workflows="workflows" media-type="video" v-model:version-id="draft.video_workflow_version_id" v-model:params="draft.video_params" :settings="settings" :disabled="busy||aiPrompting" hide-media-inputs @refresh="reloadWorkflows" @autofill="autofill('video')"><template #media><div v-if="videoMediaParams.length" class="media-assign"><h3>工作流输入 · 来自已勾选的视频资源</h3><div v-for="p in videoMediaParams" :key="p.key" class="media-param"><b>{{p.label||p.key}}<small>{{mediaLabel(p.type)}} · {{p.multiple?'可多选':'单选'}}</small></b><div v-if="p.multiple" class="multi-list"><label v-for="e in checkedMedia.filter(x=>x.media_type===p.type)" :key="e.resource_id"><input type="checkbox" :checked="paramHas(p.key,e.resource_id)" :disabled="busy" @change="toggleExtraParam(p.key,e.resource_id,true)"/>{{e.rank}}. {{e.label}}</label><span v-if="!checkedMedia.some(x=>x.media_type===p.type)" class="muted">视频资源中暂无已勾选的{{mediaLabel(p.type)}}素材，请先在右侧勾选</span></div><select v-else :value="draft.video_params[p.key]??''" :disabled="busy" @change="toggleExtraParam(p.key,Number(($event.target as HTMLSelectElement).value)||0,false)"><option value="">自动（按勾选顺序）</option><option v-for="e in checkedMedia.filter(x=>x.media_type===p.type)" :key="e.resource_id" :value="e.resource_id">{{e.rank}}. {{e.label}}</option></select></div><p class="muted">留空的单选输入在生成预检时按勾选顺序自动填入第一个匹配素材；多选按编号顺序整组填入。</p></div></template><template #after-parameters><div class="workflow-generate"><small>先根据已勾选上下文生成提示词，确认工作流参数后生成视频候选</small><div class="workflow-actions"><button :disabled="busy||aiPrompting||!videoPromptKey(videoWorkflow)" @click="aiVideoPrompt">{{aiPrompting?'正在生成提示词…':'/生成视频提示词'}}</button><button class="primary" :disabled="busy||aiPrompting||!draft.video_workflow_version_id" @click="prepare('video')">生成视频候选</button></div></div></template></DirectorWorkflowControls><label>视频输入模式<select v-model="draft.video_mode" :disabled="busy"><option v-if="videoWorkflow&&!videoWorkflow.modes.includes(draft.video_mode)" :value="draft.video_mode">原模式不受支持，请重新选择</option><option v-for="m in videoWorkflow?.modes||['manual']" :key="m" :value="m">{{modeLabels[m]}}</option></select></label><p class="muted">首尾帧能力来自明确用途绑定。音频能力未确认时按画面制作，对白保留用于后期配音。</p>

<div class="video-direction"><div class="prompt-sources"><h3>视频提示词来源</h3><p class="muted">修改来源后，请回到上方工作流参数底部重新点击“/生成视频提示词”。</p><p>总时长 {{active.duration}} 秒 · 项目画幅 {{active.aspect_ratio}}（对应上方 duration / size）</p><label v-for="[key,label] in promptFields" :key="key">{{label}}<textarea v-model="draft.prompt_inputs[key]" rows="3" @input="markPromptInput(key)" :disabled="busy||aiPrompting"/></label><label v-for="asset in active.assets.filter(a=>a.enabled)" :key="assetPromptKey(asset)">{{asset.name}} · 参考资产描述<textarea :value="assetPromptDescription(asset)" rows="3" :disabled="busy||aiPrompting" @input="draft.prompt_asset_descriptions[assetPromptKey(asset)]=($event.target as HTMLTextAreaElement).value"/></label><p>来源修改只保存在当前镜头制作草稿，不覆盖原剧本或项目公共资产。配乐固定为 N/A。</p></div></div></section>
<section class="task-list"><h2>当前镜头任务</h2><p v-if="!active.tasks.length" class="muted">任务与产物保存在服务器，刷新页面后可以继续查看。</p><article v-for="task in active.tasks" :key="task.id"><div class="task-summary"><b>#{{task.id}} · {{scopeLabel(task.scope)}}</b><span class="task-status">{{statusMeta[task.status]?.label||task.status}}</span><div class="task-actions"><button :disabled="busy" @click="applyTaskParams(task)">应用此任务参数</button><button v-if="['PENDING','DISPATCHING','QUEUED','RUNNING'].includes(task.status)" @click="taskAction(task.id,'cancel')">取消</button><button v-if="['FAILED','CANCELLED'].includes(task.status)" @click="taskAction(task.id,'retry')">重试原参数</button><button v-if="task.status==='SUCCESS'&&task.sync_status!=='synced'" @click="taskAction(task.id,'sync')">同步产物</button></div></div><button v-if="task.error||task.sync_error" class="task-error-button" @click="openTaskError(task)">查看错误详情</button></article></section>
</main>
<aside class="inspector"><section class="res-section"><h2>视频资源</h2>
<div class="sub-head"><h3>关键帧</h3><button :disabled="busy||draft.frames.length>=30" @click="addFrame">＋ 添加关键帧</button></div><div class="frame-list"><div v-for="f in draft.frames" :key="f.id" class="frame-card" :class="{active:scope===f.id,checked:f.enabled!==false}" @click="scope=f.id;framePreviewId=null"><label class="extra-check" :aria-label="`勾选 ${scopeLabel(f.id)} 作为视频制作资源`" @click.stop><input type="checkbox" class="extra-checkbox" :checked="f.enabled!==false" :disabled="busy" @change="toggleFrameCheck(f,($event.target as HTMLInputElement).checked)"/><span v-if="f.enabled!==false" class="order">{{checkRank(`frame:${f.id}`)}}</span></label><img v-if="active.selected_frames[f.id]&&thumbs[active.selected_frames[f.id]]" class="zoomable" :src="thumbs[active.selected_frames[f.id]]" @click.stop="previewImage(active.selected_frames[f.id],scopeLabel(f.id))"/><span v-else class="frame-empty">▧</span><div class="frame-meta"><b>{{scopeLabel(f.id)}} {{f.time}}s<em v-if="f.enabled!==false" class="rank-tag">第{{checkRank(`frame:${f.id}`)}}个</em><em v-else class="rank-tag off">未勾选</em></b><small>{{active.selected_frames[f.id]?'已采用':'待制作'}}{{f.kind==='key'?' · 规划参考':''}}</small></div><div class="frame-ops"><button :disabled="busy" @click.stop="openFrameModal(f.id)">制作</button><button v-if="f.kind==='start'" :disabled="busy||!previousSelectedVideo" :title="previousSelectedVideo?`取上一镜 S${String(previousShot!.shot_no).padStart(2,'0')} 已采用视频的尾帧`:(previousShot?'上一镜还没有已采用视频':'当前是第一镜，没有上一镜')" @click.stop="usePreviousVideoTail">取上一镜尾帧</button><button v-if="f.kind==='key'" :disabled="busy" @click.stop="removeFrame(f.id)">移除</button></div></div></div><p class="muted">关键帧 / 库素材 / 镜头上下文共享勾选顺序：☑ 后按勾选先后作为视频制作资源参与生成。</p>
<div class="sub-head"><h3>库素材</h3></div><div class="extra-list"><div v-for="(e,i) in sortedExtras" :key="e.resource_id" class="extra-row" :class="{checked:e.enabled}"><label class="extra-check" :aria-label="`勾选 ${extraLabel(e)} 作为视频制作资源`"><input type="checkbox" class="extra-checkbox" :checked="e.enabled" :disabled="busy" @change="toggleExtraCheck(e,($event.target as HTMLInputElement).checked)"/><span v-if="e.enabled" class="order">{{checkRank(`extra:${e.resource_id}`)}}</span></label><img v-if="thumbs[e.resource_id]" class="zoomable" :src="thumbs[e.resource_id]" @click.stop="previewImage(e.resource_id,extraLabel(e))"/><span v-else class="extra-icon">{{extraIcon(e.media_type)}}</span><div class="extra-meta"><b>{{mediaLabel(e.media_type)}}<em v-if="e.enabled" class="rank-tag">第{{checkRank(`extra:${e.resource_id}`)}}个用于制作</em><em v-else class="rank-tag off">未勾选</em></b><input v-model="e.label" :disabled="busy" :placeholder="e.filename"/></div><div class="extra-ops"><button :disabled="busy" :aria-label="`上移 ${extraLabel(e)}`" @click="moveExtra(sortedIndexOf(e),-1)">↑</button><button :disabled="busy" :aria-label="`下移 ${extraLabel(e)}`" @click="moveExtra(sortedIndexOf(e),1)">↓</button><button :disabled="busy" @click="removeExtra(sortedIndexOf(e))">移除</button></div></div><p v-if="!draft.asset_choices.extras.length" class="empty-extras">还没有库素材。点下方「从素材库添加 / 上传」，添加后勾选左侧 ☑ 决定哪些用于视频制作。</p><p v-else-if="!draft.asset_choices.extras.some(e=>e.enabled)" class="empty-extras warn">已添加 {{draft.asset_choices.extras.length}} 个素材，均未勾选 ☑；不勾选不会参与视频生成。</p></div><div class="extra-add"><select v-model="pickerMedia" :disabled="busy" aria-label="素材类型"><option value="image">图片</option><option value="audio">声音</option><option value="video">视频</option></select><button :disabled="busy" @click="openExtrasPicker">从素材库添加 / 上传</button></div></section>
<section class="context-section"><h2>镜头上下文</h2>
<div v-for="asset in characterAssets" :key="asset.entity_id" class="context-asset" :class="{checked:isEnabledAsset(asset)}"><label class="extra-check" :aria-label="`勾选 ${asset.name} 作为视频制作参考`"><input type="checkbox" class="extra-checkbox" :checked="isEnabledAsset(asset)" :disabled="busy" @change="toggleCharacterCheck(asset.entity_id,($event.target as HTMLInputElement).checked)"/><span v-if="isEnabledAsset(asset)" class="order">{{checkRank(`char:${asset.entity_id}`)}}</span></label><img v-if="asset.resource_id&&thumbs[asset.resource_id]" class="zoomable" :src="thumbs[asset.resource_id]" @click="previewImage(asset.resource_id,asset.name)"/><span v-else class="context-icon">♙</span><div class="context-main"><b>{{asset.name}}</b><select :value="asset.variant_id??''" :disabled="busy||savingRefs||!variantsOf(asset.entity_id).length" :aria-label="`${asset.name} 服装变体`" @change="setVariant(asset.entity_id,Number(($event.target as HTMLSelectElement).value)||null)"><option value="">基本造型</option><option v-for="v in variantsOf(asset.entity_id)" :key="v.id" :value="v.id">{{v.name}}</option></select><select :value="imageModeOf(asset.entity_id)" :disabled="busy" :aria-label="`${asset.name} 参考图模式`" @change="setImageMode(asset.entity_id,($event.target as HTMLSelectElement).value as 'primary'|'turnaround')"><option value="primary">基本图</option><option value="turnaround">三视图</option></select><small v-if="imageModeOf(asset.entity_id)==='turnaround'&&!asset.resource_id">尚未生成三视图，将退回基本图</small></div><button :disabled="busy||savingRefs" @click="removeCharacter(asset.entity_id)">移除</button></div>
<div v-if="locationAsset" class="context-asset" :class="{checked:isLocationEnabled}"><label class="extra-check" :aria-label="`勾选 ${locationAsset.name} 作为视频制作参考`"><input type="checkbox" class="extra-checkbox" :checked="isLocationEnabled" :disabled="busy" @change="toggleLocationCheck(($event.target as HTMLInputElement).checked)"/><span v-if="isLocationEnabled" class="order">{{checkRank('location')}}</span></label><img v-if="locationAsset.resource_id&&thumbs[locationAsset.resource_id]" class="zoomable" :src="thumbs[locationAsset.resource_id]" @click="previewImage(locationAsset.resource_id,locationAsset.name)"/><span v-else class="context-icon">⌂</span><div class="context-main"><b>{{locationAsset.name}}</b><small>{{locationAsset.resource_id?'已采用场景参考图':'尚未采用场景参考图'}}</small></div><button :disabled="busy||savingRefs" @click="removeLocation">移除</button></div>
<div v-if="active.prop_ids.length" class="prop-list"><div v-for="pid in active.prop_ids" :key="pid" class="context-asset prop" :class="{checked:isPropEnabled(pid)}"><label class="extra-check" :aria-label="`勾选 ${propName(pid)} 作为视频制作参考`"><input type="checkbox" class="extra-checkbox" :checked="isPropEnabled(pid)" :disabled="busy" @change="togglePropCheck(pid,($event.target as HTMLInputElement).checked)"/><span v-if="isPropEnabled(pid)" class="order">{{checkRank(`prop:${pid}`)}}</span></label><img v-if="propResourceId(pid)&&thumbs[propResourceId(pid)!]" class="zoomable" :src="thumbs[propResourceId(pid)!]" :alt="propName(pid)" @click="previewImage(propResourceId(pid),propName(pid))"/><span v-else class="context-icon">▣</span><div class="context-main"><b>{{propName(pid)}}</b><small>{{propResourceId(pid)?'已绑定道具图片':'尚未绑定道具图片'}}</small></div><button :disabled="busy||savingRefs" :aria-label="`移除 ${propName(pid)}`" @click="removeProp(pid)">移除</button></div></div>
<p v-if="!active.character_ids.length&&!active.location_id&&!active.prop_ids.length" class="warning">尚未绑定角色、场景或道具。</p><button class="wide" :disabled="busy||savingRefs" @click="openContextPicker">＋ 添加角色 / 场景 / 道具</button>
<details><summary>原剧本对白 · 只读</summary><p class="dialogue">{{active.dialogue||'本镜头无对白'}}</p></details></section></aside></div>

</section></template>
<div v-if="plan.length" class="plan-layer" role="dialog" aria-modal="true" aria-label="生成计划"><section><header><div><h2>生成前检查</h2><p>{{plan.filter(p=>!p.compiled.errors.length).length}} 项可执行 · {{plan.filter(p=>p.compiled.errors.length).length}} 项需修正。不会自动采用结果。</p></div><button :disabled="busy" @click="plan=[]">关闭</button></header><article v-for="item in plan" :key="item.shot.id"><h3>镜头 {{item.shot.shot_no}} · {{scopeLabel(item.body.scope)}}</h3><p>{{item.compiled.workflow?.name}} <template v-if="item.body.generation_service==='comfyui'"> · 工作流版本 #{{item.body.workflow_version_id}}</template></p><p v-for="issue in item.compiled.errors" :key="issue" class="error">{{issue}}</p><p v-for="warning in item.compiled.warnings" :key="warning" class="warning">{{warning}}</p><details><summary>实际提交参数与素材 ID</summary><pre>{{JSON.stringify(item.compiled.params,null,2)}}</pre></details><p v-if="item.result">{{item.result}}</p></article><footer><button class="primary" :disabled="busy||!plan.some(p=>!p.compiled.errors.length&&p.result!=='已提交')" @click="executePlan">{{busy?'提交中…':'确认提交可执行项'}}</button></footer></section></div>
<div v-if="frameModal&&frame&&active" class="plan-layer frame-modal" role="dialog" aria-modal="true" :aria-label="`${scopeLabel(scope)}图片制作`"><section><header><div><small>FRAME STUDIO</small><h2>{{scopeLabel(scope)}}图片制作</h2></div><button aria-label="关闭" @click="closeFrameModal">×</button></header><div class="frame-studio"><label>时间位置（秒）<input v-model.number="frame.time" type="number" min="0" :max="active.duration" :disabled="busy||frame.kind==='start'"/></label><label>静态画面描述<textarea v-model="frame.prompt" rows="3" :disabled="busy" placeholder="只描述此时间点的构图、人物姿态与场景状态，不改写原对白"/></label><label>图片生成服务<select :value="frame.generation_service" :disabled="busy" @change="chooseImageService(($event.target as HTMLSelectElement).value as 'comfyui'|'gemini_image')"><option value="gemini_image">Gemini Image</option><option value="comfyui">ComfyUI</option></select></label>
<div v-if="frame.generation_service==='gemini_image'" class="gemini-fields"><p v-if="providerError" class="error">{{providerError}}</p><p v-if="!imageProviders.length" class="warning">暂无启用的 Gemini Image 提供方，请先在系统配置中添加。</p><label>Gemini 提供方<select v-model.number="frame.gemini_provider_id" :disabled="busy"><option :value="null">请选择提供方</option><option v-for="provider in imageProviders" :key="provider.id" :value="provider.id">{{provider.name}} · {{provider.model}}</option></select></label><label>图片尺寸（系统维护项）<select v-model="frame.gemini_params.size" :disabled="busy"><option v-for="size in imageSizes" :key="size.value" :value="size.value">{{size.label}}</option></select></label><div><div class="section-heading"><span>参考图片（可不添加，可多选）</span><button :disabled="busy" @click="fillGeminiReferences">填入本镜角色 / 场景 / 道具</button></div><MediaParameterField v-model="frame.gemini_params.reference_resource_ids" media-type="image" :multiple="true" :disabled="busy"/></div><p class="muted">使用上方静态画面描述生成图片；切换服务保留各自参数。</p></div>
<DirectorWorkflowControls v-else :key="active.id+scope" :project-id="projectId" :workflows="workflows" media-type="image" v-model:version-id="frame.workflow_version_id" v-model:params="frame.params" :settings="settings" :disabled="busy" @refresh="reloadWorkflows" @autofill="autofill(scope)"/><div class="studio-actions"><button :disabled="busy" @click="pickerTarget='frame';picker=true">上传 / 素材库</button><button class="primary" :disabled="busy||!frame.prompt.trim()||(frame.generation_service==='gemini_image'?(!frame.gemini_provider_id||!frame.gemini_params.size):!frame.workflow_version_id)" @click="prepare(scope)">生成{{scopeLabel(scope)}}候选</button></div>
<div v-if="currentFrame" class="frame-result"><DirectorMediaPreview :resource-id="currentFrame.resource_id" media-type="image" :label="scopeLabel(scope)+'候选'"/><div class="candidate-actions"><button :disabled="busy||currentFrame.is_selected" @click="adopt(currentFrame)">{{currentFrame.is_selected?'此版本已采用':'采用此帧'}}</button><button @click="compare=currentFrame">放大查看</button><button v-if="frameTakes.length>1" @click="compareVersions(currentFrame)">对比版本</button><span v-if="currentFrame.stale" class="warning">依赖已更新</span></div></div><div class="take-strip"><button v-for="take in frameTakes" :key="take.id" :class="{active:currentFrame?.id===take.id}" @click="framePreviewId=take.id"><img :src="thumbs[take.resource_id]"/>v{{take.take_no}} {{take.is_selected?'✓':''}}</button></div></div></section></div>
<div v-if="contextPicker" class="plan-layer" role="dialog" aria-modal="true" aria-label="添加镜头上下文"><section><header><div><h2>添加角色 / 场景 / 道具</h2><p>保存后立即生效；依赖旧参考的候选会标记为依赖已更新。</p></div><button aria-label="关闭" @click="contextPicker=false">×</button></header><div class="context-picker"><fieldset><legend>角色（点击卡片多选）</legend><div class="pick-grid"><button v-for="c in worldCharacters" :key="c.id" type="button" class="pick-card" :class="{picked:pickCharacters.includes(c.id)}" @click="togglePick(pickCharacters,c.id)"><span class="pick-check">{{pickCharacters.includes(c.id)?'✓':''}}</span><img v-if="c.primary_resource_id&&thumbs[c.primary_resource_id]" :src="thumbs[c.primary_resource_id]"/><span v-else class="pick-icon">♙</span><b>{{c.name}}</b><small v-if="(c.variants||[]).length">{{c.variants.length}} 个变体</small></button><p v-if="!worldCharacters.length" class="muted">读取世界资产失败或暂无角色；请先在资产选角页创建。</p></div></fieldset><fieldset><legend>场景（单选）</legend><div class="pick-grid"><button v-for="l in worldLocations" :key="l.id" type="button" class="pick-card" :class="{picked:pickLocation===l.id}" @click="pickLocation=l.id"><span class="pick-check">{{pickLocation===l.id?'✓':''}}</span><img v-if="l.primary_resource_id&&thumbs[l.primary_resource_id]" :src="thumbs[l.primary_resource_id]"/><span v-else class="pick-icon">⌂</span><b>{{l.name}}</b></button><button type="button" class="pick-card none" :class="{picked:!pickLocation}" @click="pickLocation=null"><span class="pick-check">∅</span><b>不绑定</b></button><p v-if="!worldLocations.length" class="muted">暂无场景资产。</p></div></fieldset><fieldset><legend>道具（点击卡片多选）</legend><div class="pick-grid"><button v-for="p in worldProps" :key="p.id" type="button" class="pick-card" :class="{picked:pickProps.includes(p.id)}" @click="togglePick(pickProps,p.id)"><span class="pick-check">{{pickProps.includes(p.id)?'✓':''}}</span><img v-if="p.resource_id&&thumbs[p.resource_id]" :src="thumbs[p.resource_id]"/><span v-else class="pick-icon">▣</span><b>{{p.name}}</b></button><p v-if="!worldProps.length" class="muted">暂无道具资产。</p></div></fieldset></div><footer><button @click="contextPicker=false">取消</button><button class="primary" :disabled="savingRefs" @click="applyContext">{{savingRefs?'保存中…':'保存上下文'}}</button></footer></section></div>
<div v-if="taskErrorDetail" class="plan-layer task-error-modal" role="dialog" aria-modal="true" aria-label="任务错误详情"><section><header><h2>{{taskErrorDetail.title}}</h2><button aria-label="关闭错误详情" @click="taskErrorDetail=null">关闭</button></header><pre>{{taskErrorDetail.message}}</pre></section></div>
<div v-if="comparison" class="plan-layer" role="dialog" aria-modal="true" aria-label="候选版本对比"><section><header><h2>{{scopeLabel(comparison.scope)}}版本对比</h2><button @click="comparison=null">关闭对比</button></header><p>并排检查构图和动作；视频使用各自的播放控件。</p><label>对照版本<select v-model.number="comparisonId"><option v-for="take in comparisonOptions" :key="take.id" :value="take.id">Take {{take.take_no}}{{take.is_selected?' · 已采用':''}}</option></select></label><div class="compare-grid"><div><p>当前 · Take {{comparison.take_no}}</p><DirectorMediaPreview :resource-id="comparison.resource_id" :media-type="comparison.resource.media_type"/></div><div v-if="comparisonOther"><p>对照 · Take {{comparisonOther.take_no}}</p><DirectorMediaPreview :resource-id="comparisonOther.resource_id" :media-type="comparisonOther.resource.media_type"/></div></div></section></div>
<AssetPicker :open="picker" :media-type="pickerTarget==='frame'?'image':pickerMedia" @close="picker=false" @select="onPickerSelect"/><MediaViewer :open="!!compare" :output="compare?.resource||null" @close="compare=null"/><MediaViewer :open="!!imagePreview" :output="imagePreview" @close="imagePreview=null"/>
</div></DramaProjectShell></template>
